def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    # Probe for forgiving opponents at round 10
    if n == 10:
        return 'D'

    # Recovery period: cooperate unless opponent is extremely aggressive
    if 11 <= n <= 15:
        opp_def = sum(1 for a in opp if a == 'D')
        if opp_def > n * 0.5:
            return 'D'
        return 'C'

    # Exploit mode for forgiving opponents detected by the probe
    if n >= 16 and history[10][0] == 'D' and history[11][1] == 'C':
        last_opp = opp[-1]
        if last_opp == 'D':
            return 'C'
        if n % 5 == 0:
            return 'C'
        return 'D'

    # Aggressive detection: switch to always D if opponent defects often while we cooperate
    if n >= 8:
        opp_def = sum(1 for a in opp if a == 'D')
        my_def = sum(1 for a in me if a == 'D')
        if opp_def > n * 0.35 and my_def < n * 0.4:
            return 'D'
        if opp_def > n * 0.8:
            return 'D'

    # Normal TFT with forgiveness and endgame
    last_opp = opp[-1]
    if last_opp == 'D':
        if me[-1] == 'D' and n >= 2 and opp[-2] == 'D':
            return 'C'
        if rng.random() < 0.9:
            return 'D'
        return 'C'
    else:
        return 'C'
